				cfd->flags |= CANFD_ESI;
		} else {
			can_frame_set_cc_len(cf, msg->rx.dlc & ~ESD_USB_RTR, priv->can.ctrlmode);
			len = cf->len;
			if (msg->rx.dlc & ESD_USB_RTR) {
				cf->can_id |= CAN_RTR_FLAG;
				len = 0;
			}
		}

		if (id & ESD_USB_EXTID)
			cfd->can_id |= CAN_EFF_FLAG;

		memcpy(cfd->data, msg->rx.data_fd, len);
		stats->rx_bytes += len;
		stats->rx_packets++;

		netif_rx(skb);
	}
}

