struct esd_usb_header_msg {
	u8 len; /* total message length in 32bit words */
	u8 cmd;
	u8 rsvd[2];
};

struct esd_usb_version_msg {
	u8 len; /* total message length in 32bit words */
	u8 cmd;
	u8 rsvd;
	u8 flags;
